-- Tenant setup-invite tokens were generated with Math.random() (not a CSPRNG) and
-- stored in plaintext, unlike the equivalent password-reset/staff-invite flow which
-- correctly stores only a SHA-256 hash of a crypto.randomBytes(32) token. This
-- migration renames the column so the app can start storing only the hash.
--
-- Any tokens already sitting in this column are plaintext and, by definition, were
-- generated by the insecure method being fixed here — they cannot be meaningfully
-- "hashed in place" into valid hash-lookup values, so pending (not-yet-completed)
-- tenant invites are cleared and will need to be reissued via the admin panel.
UPDATE "User" SET "setupToken" = NULL WHERE "setupToken" IS NOT NULL;

ALTER TABLE "User" RENAME COLUMN "setupToken" TO "setupTokenHash";
ALTER INDEX "User_setupToken_key" RENAME TO "User_setupTokenHash_key";
